-- Guest Hub S2 — comments (26 Nov 2026, Ahmed — DECISIONS.md 2026-11-26 «Guest Hub S2 — comments»): Instagram and Facebook
-- comments — the two switches per channel (both OFF), the comments and their plans, a complaint's hand-off, «التعليقات»,
-- the counts, the lab items. Generated by scripts/hub-s2b-migration.mjs — never edited once applied (CLAUDE.md §12).
-- No unit mode, licence or switch is turned on. No phone number in this file. Every UPDATE / DELETE carries a WHERE.

-- ── the switches (both OFF; the system admin's) ──
alter table public.hub_channels add column if not exists comments_on boolean not null default false;
alter table public.hub_channels add column if not exists comment_private_on boolean not null default false;
alter table public.hub_channels drop constraint if exists hub_channels_comment_private;
alter table public.hub_channels add constraint hub_channels_comment_private check (not comment_private_on or comments_on);
alter table public.hub_channels drop constraint if exists hub_channels_comments_meta;
alter table public.hub_channels add constraint hub_channels_comments_meta check (not comments_on or provider = 'meta');
comment on column public.hub_channels.comments_on is 'S2 (Ahmed, 25 Nov 2026): «التعليقات» — public comments under this account''s posts are classified and answered (the system admin''s; OFF until Ahmed''s approved texts exist and he switches it on).';
comment on column public.hub_channels.comment_private_on is 'S2: «الرسائل الخاصة» — the one private message to a commenter (7 days); needs comments_on.';

-- ── Ahmed's approved texts (SOCIAL-SPEC.md §8) — one row, written only by a migration, word for word ──
create table if not exists public.hub_comment_texts (
  id integer primary key default 1 check (id = 1),
  texts jsonb,
  version text,
  approved_by text,
  set_at timestamptz not null default now()
);
comment on table public.hub_comment_texts is 'S2: Ahmed''s approved comment texts (SOCIAL-SPEC.md §8): {public: {question|price|complaint|praise: {ar: [variants], en: [variants]}}, private: {question|price|complaint: {ar, en}, other_language: {en}}}. Written only by a migration; NULL until he sends them.';
alter table public.hub_comment_texts enable row level security;
revoke all on table public.hub_comment_texts from public, anon, authenticated;
grant all on table public.hub_comment_texts to service_role;
insert into public.hub_comment_texts (id, texts) values (1, null) on conflict (id) do nothing;

-- the texts' problems (empty = ready) — the twin of _shared/hub/comments.ts → textsProblems (S4: no digit, no currency, no
-- «from» price, no link in a public reply)
create or replace function internal.hub_comment_texts_problems(t jsonb) returns text[]
language plpgsql immutable set search_path = '' as $$
declare
  v text[] := '{}';
  c text;
  l text;
  x text;
  i integer;
begin
  if t is null or jsonb_typeof(t) <> 'object' then return array['missing']; end if;
  foreach c in array array['question', 'price', 'complaint', 'praise'] loop
    foreach l in array array['ar', 'en'] loop
      if jsonb_typeof(t #> array['public', c, l]) <> 'array' or jsonb_array_length(t #> array['public', c, l]) = 0 then
        v := v || ('public.' || c || '.' || l);
      else
        i := 0;
        for x in select jsonb_array_elements_text(t #> array['public', c, l]) loop
          if coalesce(btrim(x), '') = '' then v := v || ('public.' || c || '.' || l || '.' || i || ':empty');
          elsif x ~ '[0-9٠-٩۰-۹]' then v := v || ('public.' || c || '.' || l || '.' || i || ':digit');
          elsif x ~* '(ريال|ر\.س|﷼|درهم|دولار|\msar\M|\msr\M|\musd\M|\$|€|£|%|٪|يبدأ من|ابتداءً من|ابتداء من|\mstarting (at|from)\M)' then v := v || ('public.' || c || '.' || l || '.' || i || ':price');
          elsif char_length(x) > 300 then v := v || ('public.' || c || '.' || l || '.' || i || ':long');
          elsif x ~* '(https?://|www\.)' then v := v || ('public.' || c || '.' || l || '.' || i || ':link');
          end if;
          i := i + 1;
        end loop;
      end if;
    end loop;
  end loop;
  foreach c in array array['question', 'price'] loop
    foreach l in array array['ar', 'en'] loop
      if coalesce(btrim(t #>> array['private', c, l]), '') = '' then v := v || ('private.' || c || '.' || l); end if;
    end loop;
  end loop;
  if coalesce(btrim(t #>> '{private,other_language,en}'), '') = '' then v := v || 'private.other_language.en'::text; end if;
  return v;
end;
$$;
create or replace function internal.hub_comment_texts_ready() returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((select cardinality(internal.hub_comment_texts_problems(t.texts)) = 0 from public.hub_comment_texts t where t.id = 1), false)
$$;

-- ── the comments ──
create table if not exists public.hub_comments (
  id uuid primary key default gen_random_uuid(),
  channel_id uuid not null references public.hub_channels (id) on delete cascade,
  kind text not null check (kind in ('instagram', 'facebook')),
  comment_id text not null check (comment_id ~ '^[0-9_]{5,80}$'),
  parent_id text check (parent_id is null or parent_id ~ '^[0-9_]{5,80}$'),
  post_id text check (post_id is null or post_id ~ '^[0-9_]{5,80}$'),
  post_permalink text check (post_permalink is null or post_permalink ~ '^https://'),
  post_thumb text check (post_thumb is null or post_thumb ~ '^https://'),
  post_product text,
  is_ad boolean not null default false,
  author_id text check (author_id is null or author_id ~ '^[0-9]{3,40}$'),
  author_name text check (author_name is null or char_length(author_name) <= 120),
  body text check (body is null or char_length(body) <= 2000),
  language text check (language is null or language in ('ar', 'en', 'other')),
  class text check (class is null or class in ('question', 'price', 'complaint', 'praise', 'spam', 'other')),
  state text not null default 'new' check (state in ('new', 'processing', 'replied', 'handed_off', 'skipped', 'review', 'test', 'failed')),
  skip_reason text check (skip_reason is null or skip_reason ~ '^[a-z_]{2,40}$'),
  tester boolean not null default false,
  public_body text check (public_body is null or char_length(public_body) <= 1000),
  public_variant integer,
  public_id text,
  public_status text check (public_status is null or public_status in ('sent', 'failed', 'test')),
  public_error text check (public_error is null or public_error ~ '^[a-z0-9_]{2,40}$'),
  public_at timestamptz,
  public_by uuid references auth.users (id) on delete set null,
  private_body text check (private_body is null or char_length(private_body) <= 1000),
  private_status text check (private_status is null or private_status in ('sent', 'failed', 'test')),
  private_error text check (private_error is null or private_error ~ '^[a-z0-9_]{2,40}$'),
  private_at timestamptz,
  private_by uuid references auth.users (id) on delete set null,
  conversation_id uuid references public.hub_conversations (id) on delete set null,
  handoff_id uuid,
  staff_answered_at timestamptz,
  reviewed_at timestamptz,
  reviewed_by uuid references auth.users (id) on delete set null,
  commented_at timestamptz not null,
  received_at timestamptz not null default now(),
  claimed_at timestamptz,
  classified_at timestamptz,
  done_at timestamptz,
  attempts integer not null default 0 check (attempts between 0 and 10),
  is_test boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (channel_id, comment_id)
);
comment on table public.hub_comments is 'S2: one public comment under our Instagram / Facebook posts — what it is, why it was skipped, the reply in public and the one private message. The text is kept 12 months (hub_comments_retention); nothing is hidden or deleted on Meta automatically.';
create index if not exists hub_comments_state on public.hub_comments (state, received_at);
create index if not exists hub_comments_channel_class on public.hub_comments (channel_id, class, language) where public_status = 'sent';
create index if not exists hub_comments_parent on public.hub_comments (channel_id, parent_id) where parent_id is not null;
drop trigger if exists hub_comments_touch on public.hub_comments;
create trigger hub_comments_touch before update on public.hub_comments for each row execute function internal.stamp();
-- a commenter the system admin marked «حساب تجربة» in «التعليقات» (a Facebook commenter has no DM identity to mark)
create table if not exists public.hub_comment_testers (
  channel_id uuid not null references public.hub_channels (id) on delete cascade,
  author_id text not null check (author_id ~ '^[0-9]{3,40}$'),
  set_by uuid references auth.users (id) on delete set null,
  set_at timestamptz not null default now(),
  primary key (channel_id, author_id)
);
alter table public.hub_comments enable row level security;
alter table public.hub_comment_testers enable row level security;
revoke all on table public.hub_comments, public.hub_comment_testers from public, anon, authenticated;
grant all on table public.hub_comments, public.hub_comment_testers to service_role;

-- who may see and answer comments (public text): the inbox level, and a member of «السوشيال» or of a branch unit in scope
create or replace function internal.hub_can_comments(p_level public.perm_level) returns boolean
language sql stable security definer set search_path = '' as $$
  select internal.can('inbox', p_level)
     and exists (select 1 from public.hub_unit_members m join public.hub_units u on u.id = m.unit_id
                  where m.staff_id = auth.uid() and u.status = 'active'
                    and (u.kind = 'brand' or (u.kind = 'branch' and internal.can_branch(u.branch_slug))))
$$;
create or replace function internal.hub_tester_comment(p_comment uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((select c.tester from public.hub_comments c where c.id = p_comment), false)
$$;
revoke execute on function internal.hub_tester_comment(uuid), internal.hub_comment_texts_ready() from public, anon, authenticated;

-- a complaint's hand-off is the COMMENT's (no conversation)
alter table public.hub_handoffs alter column conversation_id drop not null;
alter table public.hub_handoffs add column if not exists comment_id uuid references public.hub_comments (id) on delete cascade;
alter table public.hub_handoffs drop constraint if exists hub_handoffs_subject;
alter table public.hub_handoffs add constraint hub_handoffs_subject check (conversation_id is not null or comment_id is not null);

-- ── ingest (social-inbound): stored once; the code rules and the gates decide whether it is processed ──
create or replace function public.hub_comment_ingest(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  ch public.hub_channels;
  u public.hub_units;
  v_kind text := p ->> 'kind';
  v_skip text := nullif(p ->> 'skip', '');
  v_id uuid;
  v_tester boolean;
  v_parent public.hub_comments;
  v_state text := 'new';
  v_test boolean := coalesce((p ->> 'is_test')::boolean, false);
begin
  if v_kind not in ('instagram', 'facebook') then return jsonb_build_object('stored', false, 'reason', 'kind'); end if;
  select * into ch from public.hub_channels x
   where x.provider = 'meta' and x.kind = case when v_kind = 'instagram' then 'instagram' else 'messenger' end and x.address = p ->> 'channel';
  if ch.id is null then return jsonb_build_object('stored', false, 'reason', 'unknown_channel'); end if;
  select * into u from public.hub_units where id = ch.unit_id;
  -- our own comment: one of our public replies (its id, or its text while the id is not recorded yet) — or a staff member's
  -- reply from the Instagram / Facebook app, which ends that thread for the assistant
  if v_skip = 'own' and nullif(p ->> 'parent_id', '') is not null then
    select * into v_parent from public.hub_comments x where x.channel_id = ch.id and x.comment_id = p ->> 'parent_id';
    if v_parent.id is not null and not (v_parent.public_id is not distinct from (p ->> 'comment_id')
         or (v_parent.public_id is null and btrim(coalesce(v_parent.public_body, '')) = btrim(coalesce(p ->> 'body', '')))) then
      update public.hub_comments set staff_answered_at = coalesce(staff_answered_at, now()) where id = v_parent.id;
    end if;
  end if;
  v_tester := exists (select 1 from public.hub_social_identities i
                       where i.channel_id = ch.id and i.tester and (i.user_id = p ->> 'author_id' or (v_kind = 'instagram' and lower(i.username) = lower(p ->> 'author_name'))))
           or exists (select 1 from public.hub_comment_testers t where t.channel_id = ch.id and t.author_id = p ->> 'author_id');
  if v_skip is null then
    if not ch.comments_on then v_skip := 'switch_off';
    elsif u.assistant_mode = 'off' then v_skip := 'unit_off';
    elsif u.social_mode = 'test' and not v_tester then v_skip := 'not_tester';
    end if;
  end if;
  if v_skip is not null then v_state := 'skipped'; end if;
  insert into public.hub_comments (channel_id, kind, comment_id, parent_id, post_id, is_ad, author_id, author_name, body, commented_at, state, skip_reason, tester, is_test)
  values (ch.id, v_kind, p ->> 'comment_id', nullif(p ->> 'parent_id', ''), nullif(p ->> 'post_id', ''), coalesce((p ->> 'ad')::boolean, false),
          nullif(p ->> 'author_id', ''), left(nullif(p ->> 'author_name', ''), 120), left(nullif(p ->> 'body', ''), 2000),
          coalesce((p ->> 'commented_at')::timestamptz, now()), v_state, v_skip, v_tester, v_test)
  on conflict (channel_id, comment_id) do nothing
  returning id into v_id;
  if v_id is null then return jsonb_build_object('stored', false, 'reason', 'duplicate'); end if;
  return jsonb_build_object('stored', true, 'id', v_id, 'process', v_state = 'new', 'skip', v_skip, 'tester', v_tester);
end;
$$;

-- ── the worker (hub-agent): claim one, then record what was done ──
create or replace function public.hub_comment_claim(p_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_comments;
  ch public.hub_channels;
  u public.hub_units;
begin
  select * into c from public.hub_comments where id = p_id for update skip locked;
  if c.id is null then return jsonb_build_object('claimed', false, 'reason', 'busy'); end if;
  if not (c.state = 'new' or (c.state = 'processing' and c.claimed_at < now() - interval '3 minutes' and c.attempts < 3)) then
    return jsonb_build_object('claimed', false, 'reason', c.state);
  end if;
  select * into ch from public.hub_channels where id = c.channel_id;
  select * into u from public.hub_units where id = ch.unit_id;
  -- the switches and the audience again (they may have changed since the comment arrived); a thread a staff member answered
  if not ch.comments_on or u.assistant_mode = 'off' or (u.social_mode = 'test' and not c.tester) or c.staff_answered_at is not null then
    update public.hub_comments set state = 'skipped', done_at = now(),
           skip_reason = case when not ch.comments_on then 'switch_off' when u.assistant_mode = 'off' then 'unit_off' when c.staff_answered_at is not null then 'staff_answered' else 'not_tester' end
     where id = c.id;
    return jsonb_build_object('claimed', false, 'reason', 'skipped');
  end if;
  update public.hub_comments set state = 'processing', claimed_at = now(), attempts = attempts + 1 where id = c.id;
  return jsonb_build_object('claimed', true,
    'comment', jsonb_build_object('id', c.id, 'kind', c.kind, 'comment_id', c.comment_id, 'post_id', c.post_id, 'is_ad', c.is_ad, 'body', c.body,
                                  'commented_at', c.commented_at, 'has_post', c.post_permalink is not null or c.post_thumb is not null, 'is_test', c.is_test),
    'channel', jsonb_build_object('id', ch.id, 'kind', ch.kind, 'address', ch.address, 'page_id', coalesce(ch.page_id, ch.address), 'private_on', ch.comment_private_on),
    'unit', jsonb_build_object('id', u.id, 'mode', u.assistant_mode),
    'texts', (select t.texts from public.hub_comment_texts t where t.id = 1),
    'used', coalesce((select jsonb_object_agg(x.class || ':' || x.language, x.n) from (
               select y.class, y.language, count(*) n from public.hub_comments y
                where y.channel_id = c.channel_id and y.public_status = 'sent' and y.class is not null and y.language is not null group by y.class, y.language) x), '{}'::jsonb),
    'models', (select s.value from public.settings s where s.key = 'hub_models'),
    'prices', (select s.value from public.settings s where s.key = 'hub_model_prices'));
end;
$$;

create or replace function public.hub_comment_done(p_id uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_comments;
  ch public.hub_channels;
  v_state text := p ->> 'state';
  v_handoff uuid;
begin
  select * into c from public.hub_comments where id = p_id for update;
  if c.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  select * into ch from public.hub_channels where id = c.channel_id;
  if v_state not in ('replied', 'handed_off', 'skipped', 'review', 'test', 'failed') then raise exception 'hub_comment_state' using errcode = '22023'; end if;
  update public.hub_comments set
    class = coalesce(p ->> 'class', class), language = coalesce(p ->> 'language', language), state = v_state,
    skip_reason = nullif(p ->> 'reason', ''), classified_at = coalesce(classified_at, case when p ? 'class' then now() end), done_at = now(),
    public_body = coalesce(left(p ->> 'public_body', 1000), public_body), public_variant = coalesce((p ->> 'public_variant')::integer, public_variant),
    public_id = coalesce(nullif(p ->> 'public_id', ''), public_id), public_status = coalesce(nullif(p ->> 'public_status', ''), public_status),
    public_error = coalesce(nullif(p ->> 'public_error', ''), public_error), public_at = case when p ? 'public_status' then now() else public_at end,
    private_body = coalesce(left(p ->> 'private_body', 1000), private_body), private_status = coalesce(nullif(p ->> 'private_status', ''), private_status),
    private_error = coalesce(nullif(p ->> 'private_error', ''), private_error), private_at = case when p ? 'private_status' then now() else private_at end,
    conversation_id = coalesce(nullif(p ->> 'conversation_id', '')::uuid, conversation_id),
    post_permalink = coalesce(nullif(p ->> 'post_permalink', ''), post_permalink), post_thumb = coalesce(nullif(p ->> 'post_thumb', ''), post_thumb),
    post_product = coalesce(nullif(p ->> 'post_product', ''), post_product)
   where id = c.id;
  -- the classifier's cost, on «السوشيال» (layer tag)
  if (p ->> 'input_tokens') is not null then
    perform internal.hub_usage_add(ch.unit_id, 'tag', 'turn', coalesce(p ->> 'model', 'claude-sonnet-5-5'), (p ->> 'input_tokens')::bigint, coalesce((p ->> 'output_tokens')::bigint, 0), c.is_test);
  end if;
  -- a complaint: the comment's hand-off — both branches (a test account's: the system admin only, S1c)
  if v_state = 'handed_off' and c.handoff_id is null then
    v_handoff := gen_random_uuid();
    insert into public.hub_handoffs (id, conversation_id, comment_id, unit_id, branch_slug, reason, summary, ref_text, is_test, both_branches)
    values (v_handoff, null, c.id, ch.unit_id, 'airport-road', 'comment_complaint',
            case when c.kind = 'instagram' then 'شكوى في تعليق على انستجرام' else 'شكوى في تعليق على فيسبوك' end, 'تعليق', c.is_test, not c.tester);
    update public.hub_comments set handoff_id = v_handoff where id = c.id;
    perform internal.hub_handoff_queue(v_handoff, 'alert');
  end if;
  return jsonb_build_object('ok', true, 'handoff_id', v_handoff);
end;
$$;

create or replace function public.hub_comments_due(p_limit integer default 10) returns uuid[]
language sql stable security definer set search_path = '' as $$
  select coalesce(array_agg(id), '{}') from (
    select c.id from public.hub_comments c
     where (c.state = 'new' and c.received_at <= now() - interval '20 seconds')
        or (c.state = 'processing' and c.claimed_at < now() - interval '3 minutes' and c.attempts < 3)
     order by c.received_at limit least(greatest(coalesce(p_limit, 10), 1), 50)) x
$$;
revoke execute on function public.hub_comment_ingest(jsonb), public.hub_comment_claim(uuid), public.hub_comment_done(uuid, jsonb), public.hub_comments_due(integer) from public, anon, authenticated;
grant execute on function public.hub_comment_ingest(jsonb), public.hub_comment_claim(uuid), public.hub_comment_done(uuid, jsonb), public.hub_comments_due(integer) to service_role;

-- ── «المحادثات» → «التعليقات» ──
create or replace function public.hub_comments_list(p jsonb default '{}'::jsonb) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_limit integer := least(greatest(coalesce((p ->> 'limit')::integer, 50), 1), 100);
  v_rows jsonb;
  v_counts jsonb;
begin
  if not internal.hub_can_comments('view') then raise exception 'not allowed' using errcode = '42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', c.id, 'kind', c.kind, 'post_permalink', c.post_permalink, 'post_thumb', c.post_thumb, 'is_ad', c.is_ad,
           'author_name', c.author_name, 'body', c.body, 'language', c.language, 'class', c.class, 'state', c.state, 'skip_reason', c.skip_reason,
           'tester', c.tester, 'public_body', c.public_body, 'public_status', c.public_status, 'public_error', c.public_error, 'public_at', c.public_at,
           'private_body', c.private_body, 'private_status', c.private_status, 'private_error', c.private_error, 'private_at', c.private_at,
           'conversation_id', c.conversation_id, 'commented_at', c.commented_at, 'received_at', c.received_at, 'done_at', c.done_at,
           'reviewed_at', c.reviewed_at, 'staff_answered_at', c.staff_answered_at,
           'can_private', c.private_status is null and c.commented_at > now() - interval '7 days' and c.parent_id is null,
           'can_public', c.public_status is distinct from 'sent' and c.parent_id is null)
         order by c.received_at desc), '[]'::jsonb) into v_rows
    from (select * from public.hub_comments x
           where (not x.is_test or coalesce((p ->> 'test')::boolean, false))
             and (nullif(p ->> 'state', '') is null or x.state = p ->> 'state'
                  or (p ->> 'state' = 'needs_review' and x.state = 'review' and x.reviewed_at is null))
             and (nullif(p ->> 'kind', '') is null or x.kind = p ->> 'kind')
             and (nullif(p ->> 'class', '') is null or x.class = p ->> 'class')
             and (nullif(p ->> 'before', '') is null or x.received_at < (p ->> 'before')::timestamptz)
           order by x.received_at desc limit v_limit) c;
  select jsonb_build_object(
           'needs_review', count(*) filter (where x.state = 'review' and x.reviewed_at is null),
           'handed_off', count(*) filter (where x.state = 'handed_off' and x.staff_answered_at is null),
           'all', count(*)) into v_counts
    from public.hub_comments x where not x.is_test or coalesce((p ->> 'test')::boolean, false);
  return jsonb_build_object('rows', v_rows, 'counts', v_counts, 'can_edit', internal.hub_can_comments('edit'), 'system_admin', internal.is_system_admin());
end;
$$;

-- a staff reply in public or the one private message (hub-admin sends it after this, as the user)
create or replace function public.hub_comment_staff_begin(p_id uuid, p_mode text, p_body text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_comments;
  ch public.hub_channels;
begin
  if not internal.hub_can_comments('edit') then raise exception 'not allowed' using errcode = '42501'; end if;
  select * into c from public.hub_comments where id = p_id for update;
  if c.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  if p_mode not in ('public', 'private') or char_length(btrim(coalesce(p_body, ''))) not between 1 and 1000 then raise exception 'invalid' using errcode = '22023'; end if;
  if c.parent_id is not null then raise exception 'hub_comment_thread' using errcode = 'P0001'; end if;
  if p_mode = 'public' and c.public_status = 'sent' then raise exception 'hub_comment_public_sent' using errcode = 'P0001'; end if;
  if p_mode = 'private' and c.private_status is not null then raise exception 'hub_comment_private_sent' using errcode = 'P0001'; end if;
  if p_mode = 'private' and c.commented_at <= now() - interval '7 days' then raise exception 'hub_comment_private_expired' using errcode = 'P0001'; end if;
  select * into ch from public.hub_channels where id = c.channel_id;
  update public.hub_comments set staff_answered_at = coalesce(staff_answered_at, now()) where id = c.id;
  update public.hub_handoffs set first_reply_at = coalesce(first_reply_at, now()), closed_at = coalesce(closed_at, now())
   where comment_id = c.id and closed_at is null;
  return jsonb_build_object('ok', true, 'kind', c.kind, 'comment_id', c.comment_id, 'page_id', coalesce(ch.page_id, ch.address), 'channel_address', ch.address,
                            'channel_kind', ch.kind, 'is_test', c.is_test, 'body', c.body, 'commented_at', c.commented_at);
end;
$$;
create or replace function public.hub_comment_staff_finish(p_id uuid, p_mode text, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c public.hub_comments;
begin
  if not internal.hub_can_comments('edit') then raise exception 'not allowed' using errcode = '42501'; end if;
  select * into c from public.hub_comments where id = p_id for update;
  if c.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  if p_mode = 'public' then
    update public.hub_comments set public_body = left(p ->> 'body', 1000), public_status = p ->> 'status', public_error = nullif(p ->> 'error', ''),
           public_id = coalesce(nullif(p ->> 'provider_id', ''), public_id), public_at = now(), public_by = auth.uid(),
           state = case when p ->> 'status' = 'sent' and state in ('review', 'skipped', 'failed', 'test', 'new') then 'replied' else state end
     where id = c.id;
  elsif p_mode = 'private' then
    update public.hub_comments set private_body = left(p ->> 'body', 1000), private_status = p ->> 'status', private_error = nullif(p ->> 'error', ''),
           private_at = now(), private_by = auth.uid(), conversation_id = coalesce(nullif(p ->> 'conversation_id', '')::uuid, conversation_id)
     where id = c.id;
  else
    raise exception 'invalid' using errcode = '22023';
  end if;
  return jsonb_build_object('ok', true);
end;
$$;
-- «تمت المراجعة» (a comment that waits for a person; nothing is hidden or deleted on Meta)
create or replace function public.hub_comment_review(p_id uuid, p_done boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare c public.hub_comments;
begin
  if not internal.hub_can_comments('edit') then raise exception 'not allowed' using errcode = '42501'; end if;
  select * into c from public.hub_comments where id = p_id for update;
  if c.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  update public.hub_comments set reviewed_at = case when p_done then now() end, reviewed_by = case when p_done then auth.uid() end where id = c.id;
  update public.hub_handoffs set closed_at = coalesce(closed_at, now()) where comment_id = c.id and closed_at is null and p_done;
  return jsonb_build_object('ok', true, 'before', c.reviewed_at is not null);
end;
$$;
-- «حساب تجربة» for a commenter (the system admin)
create or replace function public.hub_comment_tester_set(p_id uuid, p_on boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_comments;
  v_batch uuid := gen_random_uuid();
begin
  if not internal.is_system_admin() then raise exception 'hub_system_admin_only' using errcode = '42501'; end if;
  select * into c from public.hub_comments where id = p_id;
  if c.id is null or c.author_id is null or p_on is null then raise exception 'hub_comment_author' using errcode = '22023'; end if;
  if p_on then
    insert into public.hub_comment_testers (channel_id, author_id, set_by) values (c.channel_id, c.author_id, auth.uid()) on conflict do nothing;
  else
    delete from public.hub_comment_testers where channel_id = c.channel_id and author_id = c.author_id;
  end if;
  update public.hub_comments set tester = p_on where channel_id = c.channel_id and author_id = c.author_id;
  insert into public.audit_log (actor_id, actor_label, entity, entity_id, branch, action, old, new, batch_id)
  values (auth.uid(), coalesce((select st.full_name from public.staff st where st.user_id = auth.uid()), 'system'), 'hub_comment_testers', c.channel_id::text, null, 'update',
          jsonb_build_object('tester', c.tester), jsonb_build_object('tester', p_on), v_batch);
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'before', c.tester);
end;
$$;
-- the two switches (the system admin's): «التعليقات» needs Ahmed's approved texts
create or replace function public.hub_comment_switch_set(p_channel uuid, p_comments boolean, p_private boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  ch public.hub_channels;
  v_batch uuid;
begin
  if not internal.is_system_admin() then raise exception 'hub_system_admin_only' using errcode = '42501'; end if;
  select * into ch from public.hub_channels where id = p_channel for update;
  if ch.id is null or ch.provider <> 'meta' then raise exception 'not_found' using errcode = '22023'; end if;
  if p_comments is null or p_private is null then raise exception 'invalid' using errcode = '22023'; end if;
  if p_private and not p_comments then raise exception 'hub_comment_private_needs_comments' using errcode = 'P0001'; end if;
  if p_comments and not ch.comments_on and not internal.hub_comment_texts_ready() then raise exception 'hub_comment_texts' using errcode = 'P0001'; end if;
  if p_comments and ch.verified_at is null then raise exception 'hub_channel_unverified' using errcode = 'P0001'; end if;
  if ch.comments_on = p_comments and ch.comment_private_on = p_private then raise exception 'nothing to change' using errcode = '22023'; end if;
  v_batch := internal.begin_batch();
  update public.hub_channels set comments_on = p_comments, comment_private_on = p_private where id = ch.id;
  -- the channels' audit trigger names its columns (not these two): the change is written here, one row of the batch
  insert into public.audit_log (actor_id, actor_label, entity, entity_id, branch, action, old, new, batch_id)
  values (auth.uid(), coalesce((select st.full_name from public.staff st where st.user_id = auth.uid()), 'system'), 'hub_channels', ch.id::text, null, 'update',
          jsonb_build_object('comments_on', ch.comments_on, 'comment_private_on', ch.comment_private_on),
          jsonb_build_object('comments_on', p_comments, 'comment_private_on', p_private), v_batch);
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'before', jsonb_build_object('comments', ch.comments_on, 'private', ch.comment_private_on));
end;
$$;
create or replace function public.hub_comment_settings() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not internal.can('assistant', 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  return jsonb_build_object(
    'channels', coalesce((select jsonb_agg(jsonb_build_object('id', ch.id, 'kind', ch.kind, 'name', ch.display_name, 'comments_on', ch.comments_on, 'private_on', ch.comment_private_on, 'verified', ch.verified_at is not null) order by ch.kind)
                            from public.hub_channels ch where ch.provider = 'meta'), '[]'::jsonb),
    'texts_ready', internal.hub_comment_texts_ready(),
    'texts_missing', to_jsonb(internal.hub_comment_texts_problems((select t.texts from public.hub_comment_texts t where t.id = 1))),
    'system_admin', internal.is_system_admin());
end;
$$;
-- «التقارير»: the comments by class and what became of them (no text)
create or replace function public.hub_comment_counts(p_from date, p_to date) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not (internal.can('reports', 'view') or internal.hub_can_comments('view')) then raise exception 'not allowed' using errcode = '42501'; end if;
  return coalesce((select jsonb_build_object(
      'total', count(*),
      'by_class', jsonb_build_object('question', count(*) filter (where class = 'question'), 'price', count(*) filter (where class = 'price'),
                                     'complaint', count(*) filter (where class = 'complaint'), 'praise', count(*) filter (where class = 'praise'),
                                     'spam', count(*) filter (where class = 'spam'), 'other', count(*) filter (where class = 'other'),
                                     'none', count(*) filter (where class is null)),
      'by_state', jsonb_build_object('replied', count(*) filter (where state = 'replied'), 'handed_off', count(*) filter (where state = 'handed_off'),
                                     'review', count(*) filter (where state = 'review'), 'skipped', count(*) filter (where state = 'skipped'),
                                     'test', count(*) filter (where state = 'test'), 'failed', count(*) filter (where state = 'failed')),
      'by_kind', jsonb_build_object('instagram', count(*) filter (where kind = 'instagram'), 'facebook', count(*) filter (where kind = 'facebook')),
      'private_sent', count(*) filter (where private_status = 'sent'))
    from public.hub_comments c
   where not c.is_test and (c.received_at at time zone 'Asia/Riyadh')::date between p_from and p_to), '{}'::jsonb);
end;
$$;
revoke execute on function public.hub_comments_list(jsonb), public.hub_comment_staff_begin(uuid, text, text), public.hub_comment_staff_finish(uuid, text, jsonb),
  public.hub_comment_review(uuid, boolean), public.hub_comment_tester_set(uuid, boolean), public.hub_comment_switch_set(uuid, boolean, boolean),
  public.hub_comment_settings(), public.hub_comment_counts(date, date) from public, anon;
grant execute on function public.hub_comments_list(jsonb), public.hub_comment_staff_begin(uuid, text, text), public.hub_comment_staff_finish(uuid, text, jsonb),
  public.hub_comment_review(uuid, boolean), public.hub_comment_tester_set(uuid, boolean), public.hub_comment_switch_set(uuid, boolean, boolean),
  public.hub_comment_settings(), public.hub_comment_counts(date, date) to authenticated;

-- ── retention: the comment's words and the author's name 12 months, as the conversations ──
create or replace function internal.hub_comments_retention() returns integer
language plpgsql security definer set search_path = '' as $$
declare v_n integer;
begin
  update public.hub_comments set body = null, author_name = null, public_body = null, private_body = null
   where received_at < now() - interval '12 months' and (body is not null or author_name is not null or public_body is not null or private_body is not null);
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;
select cron.schedule('hub-comments-retention', '23 3 2 * *', 'select internal.hub_comments_retention()');

create or replace function internal.hub_handoff_queue(p_handoff uuid, p_kind text, p_now timestamptz default now()) returns integer
language plpgsql security definer set search_path = '' as $$
declare
  h public.hub_handoffs;
  v_channel uuid;
  v_n integer := 0;
begin
  select * into h from public.hub_handoffs where id = p_handoff for update;
  if h.id is null or h.closed_at is not null then return 0; end if;
  v_channel := internal.hub_branch_channel(h.branch_slug);
  -- S1c (Ahmed, 25 Nov 2026): a test account's conversation alerts only the system admin — never a reception slot
  -- S2: a comment of a test account too (its complaint's hand-off has no conversation)
  if internal.hub_tester_conversation(h.conversation_id) or internal.hub_tester_comment(h.comment_id) then
    if p_kind = 'alert' and v_channel is not null and internal.hub_system_admin_recipient() is not null
       and not exists (select 1 from public.hub_staff_sends x where x.handoff_id = h.id and x.recipient_id = internal.hub_system_admin_recipient()) then
      insert into public.hub_staff_sends (kind, handoff_id, recipient_id, channel_id, template, is_test)
      values ('alert', h.id, internal.hub_system_admin_recipient(), v_channel, 'hub_staff_alert', h.is_test);
      v_n := 1;
    end if;
    if p_kind = 'alert' then
      update public.hub_handoffs set alerted_at = p_now, status = case when v_n > 0 then 'alerted' else 'email_only' end where id = h.id;
    else
      update public.hub_handoffs set escalated_at = p_now where id = h.id;
    end if;
    return v_n;
  end if;
  -- S2a (Ahmed, 25 Nov 2026): no branch known on «السوشيال» → both branches; the first to reply takes it
  if h.both_branches then
    v_n := internal.hub_both_alert(h.id, p_kind, false, p_now);
    if p_kind = 'alert' then
      update public.hub_handoffs set alerted_at = p_now, status = case when v_n > 0 then 'alerted' else 'email_only' end where id = h.id;
    else
      update public.hub_handoffs set escalated_at = p_now where id = h.id;
    end if;
    return v_n;
  end if;
  if p_kind = 'alert' then
    if v_channel is not null then
      insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
      select 'alert', h.id, s.id, v_channel, 'hub_staff_alert', h.is_test from public.hub_staff_slots s
       where s.branch_slug = h.branch_slug and s.active and internal.hub_slot_covers(s, p_now)
      on conflict do nothing;
      get diagnostics v_n = row_count;
      if v_n = 0 then
        insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
        select 'alert', h.id, s.id, v_channel, 'hub_staff_alert', h.is_test from public.hub_staff_slots s
         where s.branch_slug = h.branch_slug and s.active and s.role = 'manager'
        on conflict do nothing;
        get diagnostics v_n = row_count;
      end if;
    end if;
    update public.hub_handoffs set alerted_at = p_now, status = case when v_n > 0 then 'alerted' else 'email_only' end where id = h.id;
  else
    if v_channel is not null then
      insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
      select 'escalation', h.id, s.id, v_channel, 'hub_staff_alert', h.is_test from public.hub_staff_slots s
       where s.branch_slug = h.branch_slug and s.active and s.role = 'manager'
         and not exists (select 1 from public.hub_staff_sends x where x.handoff_id = h.id and x.slot_id = s.id)
      on conflict do nothing;
      get diagnostics v_n = row_count;
    end if;
    update public.hub_handoffs set escalated_at = p_now where id = h.id;
  end if;
  return v_n;
end;
$$;

create or replace function public.hub_staff_sends_claim(p_limit integer default 20, p_test boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  s record;
  v_out jsonb := '[]'::jsonb;
begin
  for s in select x.*, ch.address as from_address, ch.waba_id, ch.sending_enabled, coalesce(sl.phone, rr.phone) as to_phone,
                  coalesce(sl.active, rr.active, false) as target_active, h.token, h.branch_slug, h.summary, h.ref_text, h.reason, h.conversation_id,
                  h.closed_at, h.first_reply_at, h.both_branches, h.comment_id
             from public.hub_staff_sends x
             left join public.hub_channels ch on ch.id = x.channel_id
             left join public.hub_staff_slots sl on sl.id = x.slot_id
             left join public.hub_report_recipients rr on rr.id = x.recipient_id
             left join public.hub_handoffs h on h.id = x.handoff_id
            where x.status = 'queued' and x.is_test = coalesce(p_test, false) order by x.created_at limit least(greatest(coalesce(p_limit, 20), 1), 100) for update of x skip locked loop
    -- an alert or escalation whose hand-off was answered or closed meanwhile is not sent
    if s.to_phone is null or not s.target_active or s.from_address is null
       or (s.kind in ('alert', 'escalation') and (s.closed_at is not null or s.first_reply_at is not null)) then
      update public.hub_staff_sends set status = 'skipped', error_code = case when s.from_address is null then 'no_channel' when s.to_phone is null or not s.target_active then 'no_recipient' else 'answered' end, updated_at = now()
       where id = s.id;
      continue;
    end if;
    update public.hub_staff_sends set status = 'pending', updated_at = now() where id = s.id;
    v_out := v_out || jsonb_build_object(
      'id', s.id, 'kind', s.kind, 'template', s.template, 'language', 'ar', 'is_test', s.is_test,
      'channel_id', s.channel_id, 'from', s.from_address, 'waba_id', s.waba_id, 'sending_enabled', s.sending_enabled, 'to', s.to_phone,
      'handoff', case when s.handoff_id is not null then coalesce((
        select jsonb_build_object('token', s.token, 'branch', s.branch_slug, 'both', coalesce(s.both_branches, false), 'summary', s.summary, 'ref', s.ref_text, 'reason', s.reason,
                 'guest_name', coalesce((select nullif(btrim(r.guest_name), '') from public.reservations r where r.phone = g.phone and not r.is_test order by r.created_at desc limit 1),
                                        nullif(btrim(g.wa_profile_name), '')),
                 'guest_phone', g.phone,
                 -- S1c: a social guest has no phone — the alert names the channel instead
                 'channel_kind', (select ch.kind from public.hub_channels ch where ch.id = c.channel_id))
          from public.hub_conversations c join public.guest_profiles g on g.id = c.guest_profile_id where c.id = s.conversation_id),
        -- S2: a complaint in a comment — the commenter's name, the channel «تعليق انستجرام» / «تعليق فيسبوك», no phone
        (select jsonb_build_object('token', s.token, 'branch', s.branch_slug, 'both', coalesce(s.both_branches, false), 'summary', s.summary, 'ref', s.ref_text,
                  'reason', s.reason, 'guest_name', cm.author_name, 'guest_phone', null, 'channel_kind', cm.kind || '_comment')
           from public.hub_comments cm where cm.id = s.comment_id)) end,
      'report', case when s.kind = 'report' then (select jsonb_build_object('day', d.day, 'data', d.data) from public.hub_daily_reports d where d.day = s.report_day)
                     when s.kind = 'report_test' then jsonb_build_object('day', s.report_day, 'data', s.payload) end);
  end loop;
  return v_out;
end;
$$;

create or replace function public.hub_alert_open(p_token text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare h public.hub_handoffs;
begin
  if coalesce(p_token, '') !~ '^[0-9a-f]{32}$' then return jsonb_build_object('allowed', false, 'reason', 'invalid'); end if;
  select * into h from public.hub_handoffs where token = p_token;
  if h.id is null then return jsonb_build_object('allowed', false, 'reason', 'not_found'); end if;
  if not (internal.can_conv_id(h.conversation_id, 'view') or (h.comment_id is not null and internal.hub_can_comments('view'))) then return jsonb_build_object('allowed', false, 'reason', 'forbidden'); end if;
  if h.opened_at is null then
    update public.hub_handoffs set opened_at = now(), opened_by = auth.uid(), opened_via = 'link' where id = h.id;
  end if;
  return jsonb_build_object('allowed', true, 'conversation_id', h.conversation_id, 'comment_id', h.comment_id);
end;
$$;

create or replace function public.hub_agent_kick() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_due integer;
  v_lab integer;
  v_jobs integer;
  v_alerts integer;
  v_req bigint;
begin
  select count(*) into v_due from public.hub_turns t
   where (t.status = 'pending' and t.due_at <= now() - interval '20 seconds') or (t.status = 'running' and t.claimed_at < now() - interval '3 minutes');
  select count(*) into v_lab from public.hub_eval_results r join public.hub_eval_runs u on u.id = r.run_id
   where u.status in ('queued', 'running') and (r.status = 'pending' or (r.status = 'running' and r.claimed_at < now() - interval '4 minutes'));
  select count(*) into v_jobs from public.hub_card_jobs j where j.status = 'pending' or (j.status = 'running' and j.claimed_at < now() - interval '4 minutes');
  -- H7b: a «تعلّم:» the router's call missed
  v_jobs := v_jobs + (select count(*) from public.hub_teach_jobs t where t.status = 'pending' or (t.status = 'running' and t.claimed_at < now() - interval '4 minutes'));
  select count(*) into v_alerts from public.hub_alerts a where a.kind in ('flagged_wrong', 'spike') and a.sent_at is null and a.acknowledged_at is null and not a.is_test;
  -- S2: a comment the inbound call missed, or a stuck one
  v_due := v_due + (select count(*) from public.hub_comments c where (c.state = 'new' and c.received_at <= now() - interval '20 seconds')
                                                                  or (c.state = 'processing' and c.claimed_at < now() - interval '3 minutes' and c.attempts < 3));
  if v_due + v_lab + v_jobs + v_alerts > 0 then v_req := internal.hub_agent_post('sweep'); end if;
  return jsonb_build_object('ok', true, 'due', v_due, 'lab', v_lab, 'jobs', v_jobs, 'alerts', v_alerts, 'request', v_req);
end;
$$;

-- the comment cases of «السوشيال» (SOCIAL-SPEC.md §10): each class, Arabic and English, a price question, an ad comment,
-- a reply in a thread (no model call — the code rule), spam
do $$
declare v_sort integer := coalesce((select max(sort) from public.hub_test_items), 0) + 1;
begin
  insert into public.hub_test_items (key, unit_key, language, messages, context, expect, note, tags, added_from, sort)
  select e ->> 'key', e ->> 'unit', e ->> 'language', e -> 'messages', coalesce(e -> 'context', '{}'::jsonb), e -> 'expect', e ->> 'note',
         array(select jsonb_array_elements_text(e -> 'tags')), 'seed', v_sort + (o - 1)::integer
    from jsonb_array_elements($s2b$[{"key":"c2-01","unit":"social","language":"ar","messages":["وين موقعكم بالضبط؟"],"expect":{"action":"comment","class":"question","public":true,"private":true,"handoff":false},"note":"an Arabic question under an Instagram post","tags":["comment","social","question"],"context":{"kind":"instagram"}},{"key":"c2-02","unit":"social","language":"en","messages":["Do you have rooms with a kitchen?"],"expect":{"action":"comment","class":"question","public":true,"private":true,"handoff":false},"note":"an English question under a Facebook post","tags":["comment","social","question"],"context":{"kind":"facebook"}},{"key":"c2-03","unit":"social","language":"ar","messages":["بكم الليلة؟"],"expect":{"action":"comment","class":"price","public":true,"private":true,"handoff":false},"note":"a price question: a public reply with no price (S4) and the private message","tags":["comment","social","price"],"context":{"kind":"instagram"}},{"key":"c2-04","unit":"social","language":"en","messages":["How much for 2 nights for a family?"],"expect":{"action":"comment","class":"price","public":true,"private":true,"handoff":false},"note":"an English price question with a number in it","tags":["comment","social","price"],"context":{"kind":"facebook"}},{"key":"c2-05","unit":"social","language":"ar","messages":["الغرفة كانت وسخة والاستقبال ما رد علينا طول الليل"],"expect":{"action":"comment","class":"complaint","public":true,"handoff":true},"note":"an Arabic complaint: the public apology and the team","tags":["comment","social","complaint"],"context":{"kind":"instagram"}},{"key":"c2-06","unit":"social","language":"en","messages":["Worst stay ever, nobody answered the phone and they charged me twice"],"expect":{"action":"comment","class":"complaint","public":true,"handoff":true},"note":"an English complaint on Facebook","tags":["comment","social","complaint"],"context":{"kind":"facebook"}},{"key":"c2-07","unit":"social","language":"ar","messages":["مكان رائع وخدمة مم